"""Lexically varied corpus for the compression test.

ASCII_CORPUS is one sentence repeated; it has only 24 distinct byte pairs and
collapses to a single token after ~90 merges, so it CANNOT support a
compression sweep. This corpus has 336 distinct bigrams against a maximum of
104 merges probed — roughly 3x headroom.
"""

# Two pairs engineered to occur an equal number of times, so the tokenizer's
# tie-break rule is exercised rather than avoided.
TIE_CORPUS = ("AB" * 50) + ("CD" * 50)

ROUNDTRIP_CASES = [
    "",
    "a",
    "hello world",
    "the cat sat on the mat",
    "\u5317\u4eac\u6b22\u8fce\u60a8",          # CJK
    "\U0001f30d\U0001f680\u2728",                # emoji, incl. non-BMP
    "cafe\u0301 nai\u0308ve",                     # combining marks
    "\u00e9\u00e8\u00ea\u00eb",                 # precomposed latin-1
    "tab\there\nnewline",
    "   leading and trailing   ",
    "\u0000\u0001\u001f",                        # control characters
    "a" * 1000,                                     # long run
    "\u0627\u0644\u0633\u0644\u0627\u0645 \u05e9\u05dc\u05d5\u05dd",  # RTL
]

VOCAB_SIZE = 320  # 256 bytes + 64 learned merges; small enough to be fast


@pytest.fixture
def ascii_corpus():
    return ASCII_CORPUS


@pytest.fixture
def unicode_corpus():
    return UNICODE_CORPUS


@pytest.fixture
def compression_corpus():
    return COMPRESSION_CORPUS


@pytest.fixture
def tie_corpus():
    return TIE_CORPUS


@pytest.fixture
def trained(ascii_corpus):
    """A tokenizer trained on the ASCII corpus at VOCAB_SIZE."""
    from tokenizer import Tokenizer
    t = Tokenizer()
    t.train(ascii_corpus, VOCAB_SIZE)
    return t


@pytest.fixture
def trained_unicode(unicode_corpus):
    from tokenizer import Tokenizer
    t = Tokenizer()
    t.train(unicode_corpus, VOCAB_SIZE)
    return t
